# persistence. Unlike rotation_payload (fixed-width fields inside one group),
# every integer carries its own minimal length prefix, so the stream needs no
# out-of-band parameters to parse. Encoding never checks the signature and
# keeps no state; authorization stays verify_rotation's sole job.
# ---------------------------------------------------------------------------

ROTATION_CERT_TAG = b"thresholdsign/rotation-cert/v1"


def _encode_varint(value: int) -> bytes:
    """4-byte unsigned big-endian length followed by the minimal unsigned BE value.

    Zero encodes as the single body byte ``00``; positive values carry no
    leading zero. Negative values are rejected by the caller (ValueError).
    """
    if not isinstance(value, int) or isinstance(value, bool):
        raise TypeError("value must be an integer")
    if value < 0:
        raise ValueError("integer values must be unsigned")
    body = value.to_bytes((value.bit_length() + 7) // 8 or 1, "big", signed=False)
    if len(body) > 0xFFFFFFFF:
        raise ValueError("integer encoding too long")
    return len(body).to_bytes(4, "big", signed=False) + body


def _read_varint(
    stream: bytes, offset: int, *, what: str = "rotation certificate"
) -> tuple[int, int]:
    """Read one length-prefixed integer at ``offset``, returning ``(value, next)``.

    Raises ValueError on truncation, an over-long or leading-zero body.
    """
    if offset + 4 > len(stream):
        raise ValueError(f"truncated {what}")
    length = int.from_bytes(stream[offset:offset + 4], "big")
    offset += 4
    if length == 0 or offset + length > len(stream):
        raise ValueError(f"truncated {what}")
    body = stream[offset:offset + length]
    # The single byte 00 is the canonical zero; any longer body starting
    # with 00 (including 00 00) carries a forbidden leading zero.
    if length > 1 and body[0] == 0:
        raise ValueError("non-canonical integer encoding")
    return int.from_bytes(body, "big", signed=False), offset + length


def _read_id_list(stream: bytes, offset: int, *, name: str) -> tuple[tuple[int, ...], int]:
    """Read a 4-byte-counted, strictly increasing list of positive integers."""
    if offset + 4 > len(stream):
        raise ValueError("truncated rotation certificate")
    count = int.from_bytes(stream[offset:offset + 4], "big")
    offset += 4
    if count == 0:
        raise ValueError(f"{name} must be non-empty")
    ids = []
    for _ in range(count):
        member_id, offset = _read_varint(stream, offset)
        if member_id == 0:
            raise ValueError(f"{name} must be positive")
        if ids and member_id <= ids[-1]:
            raise ValueError(f"{name} must be strictly increasing and unique")
        ids.append(member_id)
    return tuple(ids), offset


def _check_rotation_fields(
    old: int,
    new: int,
    ids: tuple[int, ...],
    t: int,
    q: int,
    p: int,
    g: int,
    sig: AggregateSignature,
) -> None:
    """Type- and structure-check every Rotation field, mirroring verify_rotation.

    The signature is checked for structural legality only; whether it actually
    authorizes the rotation is left to verify_rotation.
    """
    for name, value in (
        ("old", old),
        ("new", new),
        ("t", t),
        ("q", q),
        ("p", p),
        ("g", g),
    ):
        if not isinstance(value, int) or isinstance(value, bool):
            raise TypeError(f"{name} must be an integer")
    if not isinstance(ids, tuple):
        raise TypeError("ids must be a tuple")
    for member_id in ids:
        if not isinstance(member_id, int) or isinstance(member_id, bool):
            raise TypeError("member ids must be integers")
    if not isinstance(sig, AggregateSignature):
        raise TypeError("sig must be an AggregateSignature instance")
    if not isinstance(sig.R, int) or isinstance(sig.R, bool):
        raise TypeError("sig.R must be an integer")
    if not isinstance(sig.z, int) or isinstance(sig.z, bool):
        raise TypeError("sig.z must be an integer")
    if not isinstance(sig.signer_ids, tuple):
        raise TypeError("sig.signer_ids must be a tuple")
    for signer_id in sig.signer_ids:
        if not isinstance(signer_id, int) or isinstance(signer_id, bool):
            raise TypeError("signer ids must be integers")

    _validate_feldman_parameters(q, p, g)
    for name, public_key in (("old", old), ("new", new)):
        if not 0 < public_key < p:
            raise ValueError(f"{name} public key must satisfy 0 < {name} < p")
        if pow(public_key, q, p) != 1:
            raise ValueError(f"{name} public key must lie in the order-q subgroup")
    if not ids:
        raise ValueError("at least one member id is required")
    for member_id in ids:
        if not 0 < member_id < q:
            raise ValueError("member ids must satisfy 1 <= id <= q - 1")
    if any(ids[index] >= ids[index + 1] for index in range(len(ids) - 1)):
        raise ValueError("member ids must be strictly increasing and unique")

    return tuple(siblings)


def seal_multi(key, records, indices, *, seed=800):
    """Return (proof, signature) for a threshold-signed multi-proof statement."""
    message, proof = make_multi_proof(records, indices)
    signature = sign_message(key, message, seed=seed + sum(indices))
    return proof, signature


class AuditMultiProofDataTest(unittest.TestCase):
    def test_field_order_and_positional_construction(self):
        self.assertEqual(
            [field.name for field in dataclasses.fields(AuditMultiProof)],
            ["indices", "n", "records", "siblings"],
        )
        audit = SigningAudit(b"a")
        records = ((b"m", audit),)
        siblings = (b"s" * 32,)
        proof = AuditMultiProof((1,), 3, records, siblings)
        self.assertEqual(
            (proof.indices, proof.n, proof.records, proof.siblings),
            ((1,), 3, records, siblings),
        )

    def test_frozen_value_equality_and_hash(self):
        audit = SigningAudit(b"a")
        records = ((b"m", audit),)
        siblings = (b"s" * 32, b"t" * 32)
        proof = AuditMultiProof((1, 3), 4, records, siblings)
        same = AuditMultiProof(indices=(1, 3), n=4, records=records, siblings=siblings)
        self.assertEqual(proof, same)
        self.assertEqual(hash(proof), hash(same))
        for changed in (
            AuditMultiProof((1, 2), 4, records, siblings),
            AuditMultiProof((1, 3), 5, records, siblings),
            AuditMultiProof((1, 3), 4, ((b"x", audit),), siblings),
            AuditMultiProof((1, 3), 4, records, (b"s" * 32,)),
        ):
            self.assertNotEqual(proof, changed)
        with self.assertRaises(FrozenInstanceError):
            proof.n = 5


class MakeMultiProofTest(unittest.TestCase):
    def setUp(self):
        self.key = make_key()
        self.records = tuple(
            make_record(self.key, f"message-{i}".encode(), seed=100 + 10 * i)
            for i in range(5)
        )

    def _records_of_size(self, n):
        base = list(self.records)
        if n > len(base):
            base.extend(
                make_record(self.key, f"extra-{j}".encode(), seed=400 + j)
                for j in range(n - len(base))
            )
        return tuple(base[:n])

    def test_statement_layout_for_every_size_and_subset(self):
        for n in range(1, 9):
            records = self._records_of_size(n)
            root = independent_tree(records)[-1][0]
            for mask in range(1, 1 << n):
                indices = tuple(i for i in range(n) if mask & (1 << i))
                message, proof = make_multi_proof(records, indices)
                self.assertEqual(message, ROOT_TAG + u64(n) + root)
                self.assertEqual(len(message), 4 + 8 + 32)
                self.assertEqual(proof.n, n)
                self.assertTrue(all(len(s) == 32 for s in proof.siblings))

    def test_same_statement_as_single_proof(self):
        for n in range(1, 9):
            records = self._records_of_size(n)
            single_message, _ = make_proof(records, 0)
            multi_message, _ = make_multi_proof(records, tuple(range(n)))
            self.assertEqual(multi_message, single_message)

    def test_records_pair_one_to_one_with_indices(self):
        records = self.records
        indices = (0, 2, 4)
        _message, proof = make_multi_proof(records, indices)
        self.assertEqual(proof.indices, indices)
        self.assertEqual(proof.records, tuple(records[i] for i in indices))
        self.assertIs(proof.records[1][0], records[2][0])

    def test_siblings_match_independent_builder(self):
        for n in range(1, 9):
            records = self._records_of_size(n)
            levels = independent_tree(records)
            for mask in range(1, 1 << n):
                indices = tuple(i for i in range(n) if mask & (1 << i))
                _message, proof = make_multi_proof(records, indices)
                self.assertEqual(
                    proof.siblings,
                    independent_siblings(levels, indices),
                    msg=f"n={n} indices={indices}",
                )

    def test_single_index_matches_single_proof_path_except_odd_tails(self):
        # The single-leaf AuditProof always carries a (redundant) sibling
        # digest on odd-tail levels; the compact proof omits them.
        for n in range(1, 9):
            records = self._records_of_size(n)
            levels = independent_tree(records)
            for index in range(n):
                _m, single = make_proof(records, index)
                _message, multi = make_multi_proof(records, (index,))
                self.assertEqual(
                    multi.siblings, independent_siblings(levels, (index,))
                )
                self.assertEqual(multi.records, ((single.m, single.a),))
                self.assertLessEqual(len(multi.siblings), len(single.p))

    def test_proving_every_record_needs_no_siblings(self):
        for n in range(1, 9):
            records = self._records_of_size(n)
            _message, proof = make_multi_proof(records, tuple(range(n)))

